#include "test.h"
#include "../src/game/city.h"

/*
 * The table of what's seen from each roof (city_seen, generated by tools/make_city_seen.py: it has
 * the how and why). Since 2026-11-16 the walls hide together, worked out by occluder shrinking: too
 * much to work out again here. What matters is that it's sure: it never leaves out a tower that can
 * be seen (a hole in the picture). So here, lines of sight: from random eyes on random roofs (every
 * height up to CITY_SEEN_EYE over the roof), to points on every tower, against every tower as a box
 * from the ground to its roof. A tower a line reaches, through no other box, must have its bit set.
 * The tool checks the same before it writes the table: this keeps the table and the towers in
 * city.c in step (change the towers without running the tool, and lines reach towers it hid).
 * Positions as city.h has them: out along the corridor, across it
 */

// A small, repeatable random (no rand(): the same on every PC)
static unsigned int seed = 16112026u;
static int random_in(int lo, int hi)
{
	seed = seed * 1103515245u + 12345u;
	return lo + (int)((seed >> 8) % (unsigned int)(hi - lo + 1));
}

// Whether the line from (ex, ey, ez) to (px, py, pz) passes through tower b's box (from the ground
// to its roof): the slab test, in doubles (the PC's)
static bool line_through(double ex, double ey, double ez, double px, double py, double pz, const city_tower *b)
{
	const double lo_box[3] = {b->out_min, b->across_min, CITY_GROUND}, hi_box[3] = {b->out_max, b->across_max, b->height};
	const double e[3] = {ex, ey, ez}, d[3] = {px - ex, py - ey, pz - ez};
	double lo = 1e-6, hi = 1 - 1e-6;

	for (int axis = 0; axis < 3; ++axis)
	{
		if (d[axis] == 0)
		{
			if (e[axis] <= lo_box[axis] || e[axis] >= hi_box[axis])
				return false;
			continue;
		}
		{
			double t1 = (lo_box[axis] - e[axis]) / d[axis], t2 = (hi_box[axis] - e[axis]) / d[axis];

			if (t1 > t2)
			{
				const double t = t1;

				t1 = t2;
				t2 = t;
			}
			lo = t1 > lo ? t1 : lo;
			hi = t2 < hi ? t2 : hi;
		}
	}
	return lo < hi;
}

// Whether a line reaches tower t from the eye: some point on it (5 x 5 over its footprint, at its
// top and lower down) through no other tower
static bool reached(double ex, double ey, double ez, int t)
{
	const city_tower *target = &city_towers[t];

	for (int i = 0; i < 5; ++i)
		for (int k = 0; k < 5; ++k)
			for (int h = 0; h < 3; ++h)
			{
				const double px = target->out_min + 1 + (CITY_TOWER_SIZE - 2) * i / 4.0;
				const double py = target->across_min + 1 + (CITY_TOWER_SIZE - 2) * k / 4.0;
				const double pz = target->height - (h == 0 ? 1 : h == 1 ? 200 : 800);
				bool clear = true;

				for (int o = 0; o < CITY_TOWERS && clear; ++o)
					if (o != t && line_through(ex, ey, ez, px, py, pz, &city_towers[o]))
						clear = false;
				if (clear)
					return true;
			}
	return false;
}

static void the_table_never_hides_what_a_line_reaches(void)
{
	int checked = 0;

	for (int n = 0; n < 40; ++n)
	{
		int from;

		do
			from = random_in(0, CITY_TOWERS - 1);
		while (city_towers[from].kind == CITY_GUARD);
		{
			const city_tower *roof = &city_towers[from];
			const int x = random_in(roof->out_min, roof->out_max), y = random_in(roof->across_min, roof->across_max);
			const int z = roof->height + random_in(40, CITY_SEEN_EYE);
			const int patch = city_seen_patch(roof, x, y);

			for (int t = 0; t < CITY_TOWERS; ++t)
			{
				if (city_sees(from, patch, t))
					continue; // (seen: nothing to check)
				CHECK(!reached(x, y, z, t)); // hidden by the table: no line may reach it
				++checked;
			}
		}
	}
	CHECK(checked > 40 * 100); // (the table hides plenty: over 100 a roof, of 256)
}

// The patch you're on, from where you are on the roof: its four quarters, and the edges belong
// to one of them
static void a_roof_s_four_patches(void)
{
	const city_tower *hub = city_tower_at(CITY_HUB_COLUMN, CITY_HUB_ROW);

	CHECK_EQ(0, city_seen_patch(hub, hub->out_min, hub->across_min));
	CHECK_EQ(1, city_seen_patch(hub, hub->out_max, hub->across_min));
	CHECK_EQ(2, city_seen_patch(hub, hub->out_min + 10, hub->across_max));
	CHECK_EQ(3, city_seen_patch(hub, hub->out_min + 250, hub->across_min + 250));
	CHECK_EQ(0, city_seen_patch(hub, hub->out_min + 249, hub->across_min + 249));
}

// It hides most of the city: from the CD block's hub, under half the towers are left; and a roof
// always sees itself and the towers touching it
static void from_the_hub_most_towers_are_hidden(void)
{
	const int hub = CITY_HUB_ROW * CITY_COLUMNS + CITY_HUB_COLUMN;

	for (int patch = 0; patch < CITY_SEEN_PATCHES * CITY_SEEN_PATCHES; ++patch)
	{
		int count = 0;

		for (int tower = 0; tower < CITY_TOWERS; ++tower)
			count += city_sees(hub, patch, tower) ? 1 : 0;
		CHECK(count < CITY_TOWERS / 2);
		CHECK(city_sees(hub, patch, hub));
		CHECK(city_sees(hub, patch, hub + 1));			  // the tower east of it, touching (its block's)
		CHECK(city_sees(hub, patch, hub + CITY_COLUMNS)); // and south
	}
}

// Through the corridor's doorway (city_seen_doorway): no line from a point of the doorway (any
// height up to CITY_DOORWAY_EYE) reaches a tower it leaves out; the entry's roof is seen; and it
// leaves out most of the city
static void through_the_doorway_only_what_can_be_seen(void)
{
	const int entry = CITY_ENTRY_ROW * CITY_COLUMNS; // column 0: the entry's roof
	int count = 0;

	for (int t = 0; t < CITY_TOWERS; ++t)
		count += city_seen_has(city_seen_doorway, t) != 0;
	CHECK(city_seen_has(city_seen_doorway, entry) != 0);
	CHECK(count < CITY_TOWERS / 2);
	for (int n = 0; n < 8; ++n)
	{
		const int y = random_in(0, CITY_DOORWAY_WIDE), z = random_in(0, CITY_DOORWAY_EYE);

		for (int t = 0; t < CITY_TOWERS; ++t)
			if (city_seen_has(city_seen_doorway, t) == 0)
				CHECK(!reached(CORRIDOR_LENGTH, y, z, t));
	}
}

/*
 * Over the streets (city_seen_street, 2026-11-18): the same, from random eyes over random pieces of
 * street, from as high as an eye gets there (city_street_eye) to 400 below it (mid-jump, falling)
 */
static void over_a_street_only_what_can_be_seen(void)
{
	const city_tower *first = city_tower_at(0, 0), *last = city_tower_at(CITY_COLUMNS - 1, CITY_ROWS - 1);
	int checked = 0, eyes = 0;

	while (eyes < 40)
	{
		const int x = random_in(first->out_min, last->out_max), y = random_in(first->across_min, last->across_max);
		// (the lowest eye there is: any piece, so we can read its eye)
		const int piece = city_street_under(x, y, CITY_STREET_NO_EYE + 1);

		if (piece < 0)
			continue; // over a roof, or a street only guard pages stand by
		{
			const int z = city_street_eye[piece] - random_in(0, 400);

			CHECK_EQ(piece, city_street_under(x, y, z));
			for (int t = 0; t < CITY_TOWERS; ++t)
				if (city_seen_has(city_seen_street[piece], t) == 0)
				{
					CHECK(!reached(x, y, z, t)); // hidden by the table: no line may reach it
					++checked;
				}
		}
		++eyes;
	}
	CHECK(checked > 40 * 100); // (it hides plenty there too)
}

/*
 * Where the pieces are (city.h has their order): every one is somewhere, a roof's no street, and
 * past the bank's edges there's none. And the eye: over the highest roof beside it, never lower
 */
static void the_street_pieces(void)
{
	static bool hit[CITY_STREET_PIECES];
	const city_tower *a = city_tower_at(1, 0), *b = city_tower_at(2, 0);
	const city_tower *entry = city_tower_at(0, CITY_ENTRY_ROW);
	int count = 0;

	// The first: the street between columns 1 and 2, beside row 0's first half
	CHECK_EQ(0, city_street_under(a->out_max + 1, b->across_min + 10, CITY_STREET_NO_EYE));
	CHECK_EQ(1, city_street_under(a->out_max + 1, b->across_min + 260, CITY_STREET_NO_EYE));
	// The first running out: between rows 1 and 2, beside column 0
	CHECK_EQ(CITY_STREETS * CITY_STREET_ALONG,
			 city_street_under(entry->out_min + 10, city_tower_at(0, 1)->across_max + 1, CITY_STREET_NO_EYE));
	// The first crossing
	CHECK_EQ(2 * CITY_STREETS * CITY_STREET_ALONG,
			 city_street_under(a->out_max + 1, city_tower_at(0, 1)->across_max + 1, CITY_STREET_NO_EYE));
	// A roof isn't a street; nor's past the bank's far edge
	CHECK_EQ(-1, city_street_under(entry->out_min + 250, entry->across_min + 250, CITY_STREET_NO_EYE));
	CHECK_EQ(-1, city_street_under(city_tower_at(15, 0)->out_max + 50, a->across_min + 10, CITY_STREET_NO_EYE));
	CHECK_EQ(-1, city_street_under(entry->out_min - 50, entry->across_min + 10, CITY_STREET_NO_EYE));
	// Too high over it (as up the lift): none
	CHECK_EQ(-1, city_street_under(a->out_max + 1, b->across_min + 10, 5000));
	// Every piece is somewhere (a walk over the bank, every 50)
	for (int x = city_tower_at(0, 0)->out_min; x < city_tower_at(15, 0)->out_max; x += 50)
		for (int y = city_tower_at(0, 0)->across_min; y < city_tower_at(0, 15)->across_max; y += 50)
		{
			const int piece = city_street_under(x, y, CITY_STREET_NO_EYE);

			if (piece >= 0 && !hit[piece])
				hit[piece] = true, ++count;
		}
	CHECK_EQ(CITY_STREET_PIECES, count);
	// The street past the entry's block (columns 1 and 2, beside row 8): column 1's rows 7-9 are
	// guard pages, column 2's roofs are -90: the eye's a jump over those, the highest you stand on
	{
		const int piece = city_street_under(a->out_max + 1, entry->across_min + 10, CITY_STREET_NO_EYE);

		CHECK(city_street_eye[piece] >= city_tower_at(2, CITY_ENTRY_ROW)->height + CITY_SEEN_EYE);
	}
}

// The bits' order (city.h, city_seen_bit): block by block, a block's four in a nibble, every tower
// a bit of its own. level.c lists its boxes the same way and checks it as it does
static void the_bits_go_block_by_block(void)
{
	static bool taken[CITY_TOWERS];
	int distinct = 0;

	CHECK_EQ(0, city_seen_bit(0));					  // (0, 0)
	CHECK_EQ(1, city_seen_bit(1));					  // (1, 0): the same block, east
	CHECK_EQ(2, city_seen_bit(CITY_COLUMNS));		  // (0, 1): south
	CHECK_EQ(3, city_seen_bit(CITY_COLUMNS + 1));	  // (1, 1)
	CHECK_EQ(4, city_seen_bit(2));					  // (2, 0): the next block
	CHECK_EQ(4 * CITY_BLOCK_COLUMNS, city_seen_bit(2 * CITY_COLUMNS)); // (0, 2): the next row of blocks
	for (int t = 0; t < CITY_TOWERS; ++t)
	{
		const int bit = city_seen_bit(t);

		CHECK(bit >= 0 && bit < CITY_TOWERS);
		if (bit >= 0 && bit < CITY_TOWERS && !taken[bit])
			taken[bit] = true, ++distinct;
	}
	CHECK_EQ(CITY_TOWERS, distinct);
}

void run_city_seen_tests(void)
{
	RUN(the_bits_go_block_by_block);
	RUN(the_street_pieces);
	RUN(over_a_street_only_what_can_be_seen);
	RUN(through_the_doorway_only_what_can_be_seen);
	RUN(the_table_never_hides_what_a_line_reaches);
	RUN(a_roof_s_four_patches);
	RUN(from_the_hub_most_towers_are_hidden);
}
